package cn.local.psqirecord;

import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;

/** Minimal SpreadsheetML writer: explicit string cells, numeric scores, no executable formulas. */
public final class Xlsx {
 public static final class Sheet {public final String name;public final List<List<Object>> rows=new ArrayList<>();public Sheet(String name){this.name=name;}public void add(Object... values){rows.add(new ArrayList<>(Arrays.asList(values)));}public void addList(List<?>values){rows.add(new ArrayList<Object>(values));}}
 private static String xml(String s){StringBuilder b=new StringBuilder();for(int offset=0;offset<s.length();){int c=s.codePointAt(offset);offset+=Character.charCount(c);if(c=='&')b.append("&amp;");else if(c=='<')b.append("&lt;");else if(c=='>')b.append("&gt;");else if(c=='\"')b.append("&quot;");else if(c=='\'')b.append("&apos;");else if(c==9||c==10||c==13||(c>=32&&c<=0xD7FF)||(c>=0xE000&&c<=0xFFFD)||(c>=0x10000&&c<=0x10FFFF))b.appendCodePoint(c);else b.append('\uFFFD');}return b.toString();}
 private static String column(int n){StringBuilder b=new StringBuilder();for(n++;n>0;n=(n-1)/26)b.insert(0,(char)('A'+(n-1)%26));return b.toString();}
 private static void part(ZipOutputStream z,String name,String content)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(content.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 public static void write(OutputStream stream,List<Sheet>sheets)throws Exception{try(ZipOutputStream z=new ZipOutputStream(stream)){StringBuilder types=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>");StringBuilder workbook=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>");StringBuilder rels=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");
  for(int i=0;i<sheets.size();i++){int n=i+1;Sheet sheet=sheets.get(i);if(sheet.rows.size()>1000000)throw new IOException("导出行数过多，请缩小筛选范围");types.append("<Override PartName=\"/xl/worksheets/sheet").append(n).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");workbook.append("<sheet name=\"").append(xml(sheet.name)).append("\" sheetId=\"").append(n).append("\" r:id=\"rId").append(n).append("\"/>");rels.append("<Relationship Id=\"rId").append(n).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet").append(n).append(".xml\"/>");writeSheet(z,sheet,n);}
  types.append("</Types>");workbook.append("</sheets></workbook>");rels.append("<Relationship Id=\"rIdStyles\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");part(z,"[Content_Types].xml",types.toString());part(z,"xl/workbook.xml",workbook.toString());part(z,"xl/_rels/workbook.xml.rels",rels.toString());part(z,"_rels/.rels","<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");part(z,"xl/styles.xml",STYLES);
 }}
 private static void writeSheet(ZipOutputStream z,Sheet sheet,int index)throws Exception{z.putNextEntry(new ZipEntry("xl/worksheets/sheet"+index+".xml"));Writer w=new OutputStreamWriter(z,StandardCharsets.UTF_8);int cols=1;for(List<Object>r:sheet.rows)cols=Math.max(cols,r.size());String last=column(cols-1)+Math.max(1,sheet.rows.size());w.write("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><dimension ref=\"A1:"+last+"\"/><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight=\"24\"/><cols>");for(int c=0;c<cols;c++){String head=sheet.rows.isEmpty()?"":String.valueOf(sheet.rows.get(0).get(c));int width=head.contains("链接")?70:head.contains("说明")||head.contains("内容")||head.contains("原始")?45:head.contains("ID")?38:head.contains("名称")?28:head.contains("日期")?15:18;w.write("<col min=\""+(c+1)+"\" max=\""+(c+1)+"\" width=\""+width+"\" customWidth=\"1\"/>");}w.write("</cols><sheetData>");
  for(int r=0;r<sheet.rows.size();r++){w.write("<row r=\""+(r+1)+"\""+(r==0?" ht=\"32\" customHeight=\"1\"":"")+">");List<Object>values=sheet.rows.get(r);for(int c=0;c<values.size();c++){Object value=values.get(c);if(value==null)continue;String ref=column(c)+(r+1);boolean number=value instanceof Number&&Double.isFinite(((Number)value).doubleValue());int style=r==0?1:number?(r%2==0?5:4):(r%2==0?3:2);if(number)w.write("<c r=\""+ref+"\" s=\""+style+"\"><v>"+value.toString()+"</v></c>");else{String text=String.valueOf(value);if(text.length()>32767)text=text.substring(0,32767);w.write("<c r=\""+ref+"\" s=\""+style+"\" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+xml(text)+"</t></is></c>");}}w.write("</row>");}w.write("</sheetData><autoFilter ref=\"A1:"+last+"\"/><pageMargins left=\"0.25\" right=\"0.25\" top=\"0.5\" bottom=\"0.5\" header=\"0.2\" footer=\"0.2\"/></worksheet>");w.flush();z.closeEntry();
 }
 private static final String STYLES="<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><numFmts count=\"1\"><numFmt numFmtId=\"164\" formatCode=\"0.##\"/></numFmts><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Microsoft YaHei\"/><color rgb=\"FF203A34\"/></font><font><b/><sz val=\"11\"/><name val=\"Microsoft YaHei\"/><color rgb=\"FFFFFFFF\"/></font></fonts><fills count=\"4\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF16756B\"/><bgColor indexed=\"64\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFF0F6F3\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border><left style=\"thin\"><color rgb=\"FFD9E4DE\"/></left><right style=\"thin\"><color rgb=\"FFD9E4DE\"/></right><top style=\"thin\"><color rgb=\"FFD9E4DE\"/></top><bottom style=\"thin\"><color rgb=\"FFD9E4DE\"/></bottom><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"6\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"center\"/></xf><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"top\"/></xf><xf numFmtId=\"0\" fontId=\"0\" fillId=\"3\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"top\"/></xf><xf numFmtId=\"164\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"164\" fontId=\"0\" fillId=\"3\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>";
}
